// lib/ai.ts
export interface Summariser {
  summarise(text: string): Promise<string>;
}

const MAX_CHARS = 20_000;

export async function summarise(text: string, provider: Summariser) {
  if (text.length > MAX_CHARS) throw new Error('Text too long');
  const started = Date.now();
  const summary = await provider.summarise(text);
  console.info('summarise', { ms: Date.now() - started, chars: text.length });
  return summary;
}

const Scope = z.object({
  deliverables: z.array(z.string()).min(1),
  deadline: z.string().nullable(),
  openQuestions: z.array(z.string()),
});

async function extractScope(brief: string) {
  for (let attempt = 1; attempt <= 2; attempt++) {
    const raw = await model.generateJson(brief, Scope);   // your provider adapter
    const parsed = Scope.safeParse(raw);
    if (parsed.success) return parsed.data;
  }
  return null; // UI: 'Could not structure this brief. Edit it manually.'
}

const cases = [
  { brief: 'Logo + 10 social posts by 15 Nov, budget ~40k', expect: { deadline: '15 Nov', minDeliverables: 2 } },
  // ...19 more, including empty, rambling and non-English briefs
];

let passed = 0;
for (const c of cases) {
  const out = await extractScope(c.brief);
  const ok = out !== null
    && out.deliverables.length >= c.expect.minDeliverables
    && (c.expect.deadline === undefined || (out.deadline ?? '').includes(c.expect.deadline));
  if (ok) passed++;
}
console.log(`${passed}/${cases.length} passed`);
